from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field
from datetime import datetime

app = FastAPI()
items = {}
next_id = 1

class ItemCreate(BaseModel):
    name: str = Field(..., min_length=1, max_length=50)
    price: float = Field(..., ge=0.01, le=9999)
    category: str = "misc"

@app.get("/items")
async def get_items(category: str | None = None):
    if category:
        return [i for i in items.values() if i["category"] == category]
    return list(items.values())

@app.get("/items/{item_id}")
async def get_item(item_id: int):
    if item_id not in items:
        raise HTTPException(404, detail="物品不存在")
    return items[item_id]

@app.post("/items", status_code=201)
async def create(item: ItemCreate):
    global next_id
    new_item = {"id": next_id, "name": item.name, "price": item.price, "category": item.category, "created_at": str(datetime.now())}
    items[next_id] = new_item
    next_id += 1
    return new_item

